import type { Mat4 } from '../math/types';

/** One instance of an object generated by a collection instance or a particle system. */
export interface EvaluatedInstance {
  /** Stable id, e.g. `${ownerId}:${systemId}:${index}`. */
  id: string;
  /** Object generating the instance (instancing empty or particle emitter). */
  ownerId: string;
  /** Evaluated object whose geometry and materials are instanced. */
  sourceId: string;
  /** Final world matrix of the instance. */
  matrix: Mat4;
}
